/**
 * Output and Input Blob Validation Utilities.
 * Enforces non-empty results, verified MIME types, and reasonable format checks.
 */

export interface ValidationResult {
  isValid: boolean;
  error?: string;
  sizeBytes: number;
  mimeType: string;
}

/**
 * Validate that an output Blob generated by a compression engine is genuine and non-empty.
 */
export function validateOutputBlob(
  blob: Blob | null | undefined,
  expectedCategory?: 'image' | 'pdf' | 'video' | 'audio'
): ValidationResult {
  if (!blob) {
    return {
      isValid: false,
      error: 'The compression engine produced an empty (null) result.',
      sizeBytes: 0,
      mimeType: '',
    };
  }

  if (blob.size === 0) {
    return {
      isValid: false,
      error: 'The compression engine produced a 0-byte output file.',
      sizeBytes: 0,
      mimeType: blob.type || 'unknown',
    };
  }

  const mime = (blob.type || '').toLowerCase();

  if (expectedCategory === 'image') {
    if (!mime.startsWith('image/') && mime !== 'application/octet-stream') {
      return {
        isValid: false,
        error: `Expected image output, but received MIME type: ${mime || 'unspecified'}.`,
        sizeBytes: blob.size,
        mimeType: mime,
      };
    }
  } else if (expectedCategory === 'pdf') {
    if (!mime.includes('pdf') && mime !== 'application/octet-stream') {
      return {
        isValid: false,
        error: `Expected PDF output, but received MIME type: ${mime || 'unspecified'}.`,
        sizeBytes: blob.size,
        mimeType: mime,
      };
    }
  } else if (expectedCategory === 'video') {
    if (!mime.startsWith('video/') && mime !== 'application/octet-stream') {
      return {
        isValid: false,
        error: `Expected video output, but received MIME type: ${mime || 'unspecified'}.`,
        sizeBytes: blob.size,
        mimeType: mime,
      };
    }
  } else if (expectedCategory === 'audio') {
    if (!mime.startsWith('audio/') && mime !== 'application/octet-stream') {
      return {
        isValid: false,
        error: `Expected audio output, but received MIME type: ${mime || 'unspecified'}.`,
        sizeBytes: blob.size,
        mimeType: mime,
      };
    }
  }

  return {
    isValid: true,
    sizeBytes: blob.size,
    mimeType: mime,
  };
}

/**
 * Validate user-selected file before queueing.
 */
export function validateInputFile(
  file: File,
  maxSizeBytes = 1024 * 1024 * 1024 // 1 GB safety limit for browser memory
): { isValid: boolean; error?: string } {
  if (!file) {
    return { isValid: false, error: 'No file selected.' };
  }

  if (file.size === 0) {
    return {
      isValid: false,
      error: `"${file.name}" is an empty 0-byte file and cannot be compressed.`,
    };
  }

  if (file.size > maxSizeBytes) {
    return {
      isValid: false,
      error: `"${file.name}" exceeds the maximum in-browser processing limit of 1 GB.`,
    };
  }

  return { isValid: true };
}
